<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Kanban Board</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    background: linear-gradient(135deg, #f5f7fb 0%, #e9eef7 100%);
    min-height: 100vh;
    padding: 32px 24px;
    color: #1f2733;
  }
  .app { max-width: 1100px; margin: 0 auto; }
  header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 28px;
    flex-wrap: wrap;
    gap: 16px;
  }
  h1 {
    font-size: 28px;
    font-weight: 700;
    letter-spacing: -0.02em;
  }
  .controls { display: flex; gap: 8px; }
  #new-card {
    padding: 10px 14px;
    border: 1px solid #d3dae6;
    border-radius: 8px;
    font-size: 14px;
    width: 260px;
    background: #fff;
    outline: none;
    transition: border-color 0.15s, box-shadow 0.15s;
  }
  #new-card:focus {
    border-color: #5b8def;
    box-shadow: 0 0 0 3px rgba(91,141,239,0.15);
  }
  #add-card {
    padding: 10px 18px;
    background: #5b8def;
    color: #fff;
    border: none;
    border-radius: 8px;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s, transform 0.05s;
  }
  #add-card:hover { background: #4a7fd8; }
  #add-card:active { transform: translateY(1px); }

  .board {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 20px;
  }
  .column {
    background: #fff;
    border: 1px solid #e3e8ef;
    border-radius: 12px;
    padding: 16px;
    display: flex;
    flex-direction: column;
    min-height: 320px;
    box-shadow: 0 1px 3px rgba(16,24,40,0.04);
  }
  .column.drag-over {
    background: #f0f5ff;
    border-color: #5b8def;
    box-shadow: 0 0 0 2px rgba(91,141,239,0.25);
  }
  .col-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 14px;
    padding-bottom: 12px;
    border-bottom: 1px solid #eef2f7;
  }
  .col-title {
    font-size: 13px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: #4a5568;
  }
  .col-todo .col-title { color: #6b7280; }
  .col-doing .col-title { color: #d97706; }
  .col-done .col-title { color: #059669; }

  .count {
    background: #eef2f7;
    color: #4a5568;
    font-size: 12px;
    font-weight: 600;
    min-width: 22px;
    height: 22px;
    padding: 0 8px;
    border-radius: 11px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }
  .col-todo .count { background: #eef2f7; color: #4a5568; }
  .col-doing .count { background: #fef3c7; color: #92400e; }
  .col-done .count { background: #d1fae5; color: #065f46; }

  .card-container {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 10px;
    padding: 2px;
  }

  .card {
    background: #fbfcfe;
    border: 1px solid #e3e8ef;
    border-radius: 8px;
    padding: 12px 14px;
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 10px;
    cursor: grab;
    transition: box-shadow 0.15s, transform 0.05s, border-color 0.15s;
    word-break: break-word;
  }
  .card:hover {
    box-shadow: 0 4px 12px rgba(16,24,40,0.08);
    border-color: #d3dae6;
  }
  .card.dragging {
    opacity: 0.4;
    cursor: grabbing;
  }
  .card-text {
    font-size: 14px;
    line-height: 1.4;
    color: #1f2733;
    flex: 1;
  }
  .card-del {
    background: transparent;
    border: none;
    color: #b0b8c4;
    font-size: 16px;
    line-height: 1;
    cursor: pointer;
    padding: 2px 6px;
    border-radius: 4px;
    transition: background 0.15s, color 0.15s;
    flex-shrink: 0;
  }
  .card-del:hover {
    background: #fee2e2;
    color: #dc2626;
  }
  .empty-hint {
    text-align: center;
    color: #b0b8c4;
    font-size: 13px;
    padding: 20px 8px;
    font-style: italic;
  }
  @media (max-width: 760px) {
    .board { grid-template-columns: 1fr; }
  }
</style>
</head>
<body>
<div class="app">
  <header>
    <h1>Kanban Board</h1>
    <div class="controls">
      <input id="new-card" type="text" placeholder="Add a new task..." maxlength="200" />
      <button id="add-card">Add</button>
    </div>
  </header>

  <div class="board">
    <section id="col-todo" class="column col-todo" data-col="todo">
      <div class="col-header">
        <span class="col-title">To Do</span>
        <span class="count">0</span>
      </div>
      <div class="card-container"></div>
    </section>

    <section id="col-doing" class="column col-doing" data-col="doing">
      <div class="col-header">
        <span class="col-title">In Progress</span>
        <span class="count">0</span>
      </div>
      <div class="card-container"></div>
    </section>

    <section id="col-done" class="column col-done" data-col="done">
      <div class="col-header">
        <span class="col-title">Done</span>
        <span class="count">0</span>
      </div>
      <div class="card-container"></div>
    </section>
  </div>
</div>

<script>
(function () {
  "use strict";

  var STORAGE_KEY = "kanban-board-state-v1";
  var columns = ["todo", "doing", "done"];
  var colElements = {
    todo: document.getElementById("col-todo"),
    doing: document.getElementById("col-doing"),
    done: document.getElementById("col-done")
  };
  var containers = {
    todo: colElements.todo.querySelector(".card-container"),
    doing: colElements.doing.querySelector(".card-container"),
    done: colElements.done.querySelector(".card-container")
  };
  var counts = {
    todo: colElements.todo.querySelector(".count"),
    doing: colElements.doing.querySelector(".count"),
    done: colElements.done.querySelector(".count")
  };

  var input = document.getElementById("new-card");
  var addBtn = document.getElementById("add-card");

  var state = loadState();

  function loadState() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return { todo: [], doing: [], done: [] };
      var parsed = JSON.parse(raw);
      columns.forEach(function (c) {
        if (!Array.isArray(parsed[c])) parsed[c] = [];
      });
      return parsed;
    } catch (e) {
      return { todo: [], doing: [], done: [] };
    }
  }

  function saveState() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    } catch (e) {}
  }

  function uid() {
    return "c" + Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
  }

  function createCardNode(card, colName) {
    var el = document.createElement("div");
    el.className = "card";
    el.draggable = true;
    el.dataset.id = card.id;
    el.dataset.col = colName;

    var text = document.createElement("div");
    text.className = "card-text";
    text.textContent = card.title;

    var del = document.createElement("button");
    del.className = "card-del";
    del.type = "button";
    del.setAttribute("aria-label", "Delete card");
    del.textContent = "×";
    del.addEventListener("click", function (e) {
      e.stopPropagation();
      deleteCard(card.id);
    });

    el.appendChild(text);
    el.appendChild(del);

    el.addEventListener("dragstart", function (e) {
      e.dataTransfer.effectAllowed = "move";
      e.dataTransfer.setData("text/plain", card.id);
      el.classList.add("dragging");
    });
    el.addEventListener("dragend", function () {
      el.classList.remove("dragging");
      columns.forEach(function (c) { colElements[c].classList.remove("drag-over"); });
    });

    return el;
  }

  function findCard(id) {
    for (var i = 0; i < columns.length; i++) {
      var idx = state[columns[i]].findIndex(function (c) { return c.id === id; });
      if (idx !== -1) return { col: columns[i], index: idx };
    }
    return null;
  }

  function deleteCard(id) {
    var found = findCard(id);
    if (!found) return;
    state[found.col].splice(found.index, 1);
    saveState();
    render();
  }

  function addCard(title) {
    var t = (title || "").trim();
    if (!t) return;
    state.todo.unshift({ id: uid(), title: t });
    saveState();
    render();
  }

  function moveCard(id, toCol, insertIndex) {
    var found = findCard(id);
    if (!found) return;
    if (!columns.indexOf(toCol) === -1) return;
    var card = state[found.col][found.index];
    state[found.col].splice(found.index, 1);
    if (typeof insertIndex !== "number" || insertIndex < 0 || insertIndex > state[toCol].length) {
      insertIndex = state[toCol].length;
    }
    state[toCol].splice(insertIndex, 0, card);
    saveState();
    render();
  }

  function render() {
    columns.forEach(function (col) {
      var container = containers[col];
      container.innerHTML = "";
      state[col].forEach(function (card) {
        container.appendChild(createCardNode(card, col));
      });
      counts[col].textContent = state[col].length;
    });
  }

  // Add card handlers
  addBtn.addEventListener("click", function () {
    var v = input.value;
    addCard(v);
    input.value = "";
    input.focus();
  });
  input.addEventListener("keydown", function (e) {
    if (e.key === "Enter") {
      addCard(input.value);
      input.value = "";
    }
  });

  // Drag and drop on columns
  columns.forEach(function (col) {
    var colEl = colElements[col];
    var container = containers[col];

    colEl.addEventListener("dragover", function (e) {
      e.preventDefault();
      e.dataTransfer.dropEffect = "move";
      colEl.classList.add("drag-over");
    });

    colEl.addEventListener("dragleave", function (e) {
      // Only remove if leaving the column entirely
      if (!colEl.contains(e.relatedTarget)) {
        colEl.classList.remove("drag-over");
      }
    });

    colEl.addEventListener("drop", function (e) {
      e.preventDefault();
      colEl.classList.remove("drag-over");
      var cardId = e.dataTransfer.getData("text/plain");
      if (!cardId) return;

      var found = findCard(cardId);
      if (!found) return;

      // Determine insertion index based on drop position relative to cards
      var targetIndex = state[col].length;
      var cards = Array.prototype.slice.call(container.querySelectorAll(".card:not(.dragging)"));
      for (var i = 0; i < cards.length; i++) {
        var rect = cards[i].getBoundingClientRect();
        var midpoint = rect.top + rect.height / 2;
        if (e.clientY < midpoint) {
          targetIndex = i;
          break;
        }
      }

      // If moving within same column and from earlier index, adjust
      if (found.col === col && found.index < targetIndex) {
        targetIndex -= 1;
      }

      moveCard(cardId, col, targetIndex);
    });
  });

  // Seed with example cards on first visit
  if (!localStorage.getItem(STORAGE_KEY)) {
    state = {
      todo: [
        { id: uid(), title: "Plan the week" },
        { id: uid(), title: "Read an article" }
      ],
      doing: [
        { id: uid(), title: "Build the kanban board" }
      ],
      done: [
        { id: uid(), title: "Set up the project" }
      ]
    };
    saveState();
  }

  render();
})();
</script>
</body>
</html>
